
CREATE TABLE books (
    id SERIAL PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    author VARCHAR(255) NOT NULL,
    publisher VARCHAR(255),
    publicationYear INTEGER,
    pages INTEGER,
    language VARCHAR(50),
    genre VARCHAR(100),
    description TEXT,
    coverImage VARCHAR(500),
    format VARCHAR(50),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

